#!/bin/sh
# Xcode Cloud: runs right after the repo is cloned, before any build action.
#
# BugWallet.xcodeproj is generated by XcodeGen from project.yml and is not
# committed (only its Package.resolved is), so generate it here.
set -euo pipefail

cd "${CI_PRIMARY_REPOSITORY_PATH:-$(dirname "$0")/..}"

if ! command -v xcodegen >/dev/null 2>&1; then
  export HOMEBREW_NO_AUTO_UPDATE=1
  export HOMEBREW_NO_INSTALL_CLEANUP=1
  brew install xcodegen
fi

xcodegen --version
xcodegen generate --spec project.yml

# Xcode Cloud never resolves packages itself; it needs the committed lock file.
RESOLVED="BugWallet.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved"
if [ ! -f "$RESOLVED" ]; then
  echo "error: $RESOLVED is missing — open the project in Xcode, let packages resolve, and commit it." >&2
  exit 1
fi
